import {defineCollection, z} from 'astro:content';
import {glob} from 'astro/loaders';

const components = defineCollection({
  loader: glob({
    pattern: '*/*.mdx',
    base: '../../packages/react/src',
    generateId: ({entry}) => entry.split('/')[0] ?? entry,
  }),
  schema: z.object({}),
});

// The company brand guidelines, generated by the logos build for the Earendil press kit.
const guidelines = defineCollection({
  loader: glob({pattern: 'BRAND-GUIDELINES.md', base: '../../packages/logos/dist/guidelines/earendil'}),
  schema: z.object({}),
});

export const collections = {components, guidelines};
